package payflow

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sync"
)

// 账本磁盘格式（单文件，JSON 一行）：
//
//	{"version":1,"balances":{"account\x00asset":1000},
//	 "settlements":[{...一笔成功结算及其当时费率...}]}
//
// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
// 不会出现“扣款无记录”或“记录无扣款”的中间状态。
const ledgerVersion = 1

// 结算结果状态，与命令行输出一一对应，可分别识别。
const (
	StatusSettled   = "settled"    // 成功扣款
	StatusDuplicate = "duplicate"  // 幂等重试：字段与原记录一致，返回原结算，不再扣款
	StatusConflict  = "conflict"   // 编号冲突：编号已成功但字段或费率不同
	StatusState     = "state_error"
	StatusFunds     = "insufficient_balance"
	StatusInvalid   = "invalid_parameter"
	StatusStorage   = "storage_error"
)

// 拒绝原因。
const (
	reasonEmptyID      = "intent id must not be empty"
	reasonEmptyAccount = "account must not be empty"
	reasonEmptyAsset   = "asset must not be empty"
	reasonBadAmount    = "amount must be a positive int64"
	reasonNotPending   = "intent is not pending"
	reasonFunds        = "insufficient balance for amount plus fee"
	reasonDuplicate    = "duplicate settlement attempt"
	reasonConflict     = "settlement id conflicts with a different request"
)

// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
type BalanceInit struct {
	Account string `json:"account"`
	Asset   string `json:"asset"`
	Balance int64  `json:"balance"`
}

// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/为 0”与正数。
type PaymentIntent struct {
	ID        string `json:"id"`
	Account   string `json:"account"`
	Paymaster string `json:"paymaster"`
	Asset     string `json:"asset"`
	Amount    *int64 `json:"amount"`
	Nonce     uint64 `json:"nonce"`
	State     string `json:"state"`
}

// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表。
type FeeBatch struct {
	FeeBps  int             `json:"fee_bps"`
	Intents []PaymentIntent `json:"intents"`
}

// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
type Record struct {
	ID        string `json:"id"`
	Account   string `json:"account"`
	Paymaster string `json:"paymaster"`
	Asset     string `json:"asset"`
	Amount    int64  `json:"amount"`
	Nonce     uint64 `json:"nonce"`
	FeeBps    int    `json:"fee_bps"`
	Fee       int64  `json:"fee"`
	Charged   int64  `json:"charged"`
	Seq       int64  `json:"seq"`
}

// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
type ItemResult struct {
	ID     string  `json:"id"`
	Status string  `json:"status"`
	Reason string  `json:"reason,omitempty"`
	Record *Record `json:"record,omitempty"`
}

// BatchResult 是一次提交的结果。
type BatchResult struct {
	Results []ItemResult `json:"results"`
}

// BalanceView 是一个 (账户, 资产) 组合的当前余额。
type BalanceView struct {
	Account string `json:"account"`
	Asset   string `json:"asset"`
	Balance int64  `json:"balance"`
}

// Snapshot 是账本查询结果。
type Snapshot struct {
	Balances    []BalanceView `json:"balances"`
	Settlements []Record      `json:"settlements"`
}

// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
type LedgerError struct {
	Kind    string
	Message string
}

func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }

// 错误分类。
const (
	ErrInvalid   = "invalid_parameter"
	ErrExists    = "ledger_exists"
	ErrCorrupt   = "corrupt_ledger"
	ErrStorage   = "storage_error"
	ErrClosed    = "ledger_closed"
	ErrNotInit   = "ledger_not_initialized"
	ErrOtherOpen = "ledger_open_elsewhere"
)

func ledgerError(kind, format string, args ...any) error {
	return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
}

// KindOf 返回错误的分类；非账本错误返回 "storage_error"。
func KindOf(err error) string {
	var le *LedgerError
	if errors.As(err, &le) {
		return le.Kind
	}
	return ErrStorage
}

// FailWriter 注入存储故障：返回 true 时本次持久化失败，
// 内存状态必须回滚到该项执行之前。仅用于测试。
type FailWriter interface {
	FailNextPersist() bool
}

type balanceKey struct {
	account string
	asset   string
}

type ledgerState struct {
	Version     int                `json:"version"`
	Balances    map[balanceKey]int64 `json:"-"`
	Settlements []Record           `json:"settlements"`
}

// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
// 返回同一实例并共享互斥锁，因此并发提交按同一本账本串行化。
type Ledger struct {
	path string
	mu   *sync.Mutex

	// registry 级别共享状态，见 openRegistries。
	state *ledgerState
	open  bool
	reg   *registryEntry
}

type registryEntry struct {
	mu     sync.Mutex
	state  *ledgerState
	refs   int
	sole   *Ledger // 最近一次以写模式打开的实例，用于排他性校验
}

var (
	openMu       sync.Mutex
	openRegistry = map[string]*registryEntry{}
)

// persistedState 是磁盘 JSON 的实际结构。
type persistedState struct {
	Version  int                       `json:"version"`
	Balances map[string]json.RawMessage `json:"balances"`
	Records  []Record                  `json:"settlements"`
}

// MarshalJSON 让复合键以 "account\x00asset" 落盘。
func (s *ledgerState) MarshalJSON() ([]byte, error) {
	bal := make(map[string]int64, len(s.Balances))
	for k, v := range s.Balances {
		bal[encodeBalanceKey(k)] = v
	}
	return json.Marshal(struct {
		Version     int            `json:"version"`
		Balances    map[string]int64 `json:"balances"`
		Settlements []Record       `json:"settlements"`
	}{s.Version, bal, s.Settlements})
}

func encodeBalanceKey(k balanceKey) string { return k.account + "\x00" + k.asset }

func decodeBalanceKey(raw string) (balanceKey, bool) {
	for i := 0; i < len(raw); i++ {
		if raw[i] == 0 {
			return balanceKey{account: raw[:i], asset: raw[i+1:]}, true
		}
	}
	return balanceKey{}, false
}

func decodeState(p persistedState) (*ledgerState, error) {
	if p.Version != ledgerVersion {
		return nil, ledgerError(ErrCorrupt, "unsupported ledger version %d", p.Version)
	}
	if p.Balances == nil {
		return nil, ledgerError(ErrCorrupt, "missing balances section")
	}
	bals := make(map[balanceKey]int64, len(p.Balances))
	for key, raw := range p.Balances {
		k, ok := decodeBalanceKey(key)
		if !ok {
			return nil, ledgerError(ErrCorrupt, "malformed balance key %q", key)
		}
		var v int64
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, ledgerError(ErrCorrupt, "balance for %s/%s is not an int64: %v", k.account, k.asset, err)
		}
		if v < 0 {
			return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", k.account, k.asset)
		}
		bals[k] = v
	}
	seen := map[string]bool{}
	for i, r := range p.Records {
		if r.ID == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %d has empty id", i)
		}
		if seen[r.ID] {
			return nil, ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
		}
		seen[r.ID] = true
		if r.Amount <= 0 || r.Charged <= 0 || r.Fee < 0 || r.Charged != addChecked(r.Amount, r.Fee) {
			return nil, ledgerError(ErrCorrupt, "settlement %q has inconsistent amounts", r.ID)
		}
		if r.Account == "" || r.Asset == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
		}
		if r.FeeBps < 0 || r.FeeBps > 10000 {
			return nil, ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
		}
	}
	return &ledgerState{Version: p.Version, Balances: bals, Settlements: p.Records}, nil
}

func addChecked(a, b int64) int64 {
	if b > math.MaxInt64-a {
		return math.MinInt64 // 哨兵：溢出，任何真实扣款总额不可能为负
	}
	return a + b
}

// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
// 任一不合法则返回 ErrInvalid 且不创建任何文件；
// 路径上已有账本文件则返回 ErrExists，绝不覆盖历史。
func CreateLedger(path string, init []BalanceInit) error {
	if err := validateInitial(init); err != nil {
		return err
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return ledgerError(ErrStorage, "resolve path: %v", err)
	}

	openMu.Lock()
	defer openMu.Unlock()

	if _, err := os.Stat(abs); err == nil {
		return ledgerError(ErrExists, "ledger already exists at %s", abs)
	} else if !errors.Is(err, os.ErrNotExist) {
		return ledgerError(ErrStorage, "stat %s: %v", abs, err)
	}
	if reg := openRegistry[abs]; reg != nil {
		return ledgerError(ErrExists, "ledger is already initialized in this process")
	}

	state := &ledgerState{
		Version:     ledgerVersion,
		Balances:    make(map[balanceKey]int64, len(init)),
		Settlements: []Record{},
	}
	for _, b := range init {
		state.Balances[balanceKey{b.Account, b.Asset}] = b.Balance
	}
	if err := atomicWrite(abs, state); err != nil {
		return err
	}
	reg := &registryEntry{state: state}
	openRegistry[abs] = reg
	return nil
}

func validateInitial(init []BalanceInit) error {
	seen := map[balanceKey]bool{}
	for i, b := range init {
		if b.Account == "" {
			return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
		}
		if b.Asset == "" {
			return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
		}
		if b.Balance < 0 {
			return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
		}
		k := balanceKey{b.Account, b.Asset}
		if seen[k] {
			return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
		}
		seen[k] = true
	}
	return nil
}

// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
func Open(path string) (*Ledger, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, ledgerError(ErrStorage, "resolve path: %v", err)
	}

	openMu.Lock()
	defer openMu.Unlock()

	if reg := openRegistry[abs]; reg != nil {
		l := &Ledger{path: abs, mu: &reg.mu, state: reg.state, open: true, reg: reg}
		reg.refs++
		return l, nil
	}

	data, err := os.ReadFile(abs)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
		}
		return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
	}
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
	}
	var p persistedState
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&p); err != nil {
		return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
	}
	// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
	if tok, err := dec.Token(); err != io.EOF {
		if err == nil {
			return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
		}
		return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
	}
	state, err := decodeState(p)
	if err != nil {
		var le *LedgerError
		if errors.As(err, &le) && le.Kind == ErrCorrupt {
			return nil, err
		}
		return nil, ledgerError(ErrCorrupt, "%v", err)
	}

	reg := &registryEntry{state: state, refs: 1}
	openRegistry[abs] = reg
	return &Ledger{path: abs, mu: &reg.mu, state: state, open: true, reg: reg}, nil
}

// Close 释放句柄；同一进程可再次 Open 同一文件。
func (l *Ledger) Close() error {
	openMu.Lock()
	defer openMu.Unlock()
	if !l.open {
		return nil
	}
	l.open = false
	l.reg.refs--
	if l.reg.refs <= 0 {
		delete(openRegistry, l.path)
	}
	return nil
}

func (l *Ledger) locked() error {
	if !l.open {
		return ledgerError(ErrClosed, "ledger handle is closed")
	}
	return nil
}

// feeFor 计算手续费：amount*feeBps/10000 向下取整；amount>0、0<=feeBps<=10000
// 时乘积不会溢出 int64（上限 10000*MaxInt64 < MaxInt64*2^14）。
func feeFor(amount int64, feeBps int) int64 {
	hi := amount / 10000
	lo := amount % 10000
	return hi*int64(feeBps) + (lo*int64(feeBps))/10000
}

func validateIntent(it PaymentIntent) (int64, string, bool) {
	if it.ID == "" {
		return 0, reasonEmptyID, false
	}
	if it.Account == "" {
		return 0, reasonEmptyAccount, false
	}
	if it.Asset == "" {
		return 0, reasonEmptyAsset, false
	}
	if it.Amount == nil || *it.Amount <= 0 {
		return 0, reasonBadAmount, false
	}
	return *it.Amount, "", true
}

// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
// 成功后的余额；任何一项失败都不影响其余项（存储错误除外——该项回滚
// 到执行前，而已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
	if err := l.locked(); err != nil {
		return nil, err
	}
	if batch.FeeBps < 0 || batch.FeeBps > 10000 {
		return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
	}
	out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
	if len(batch.Intents) == 0 {
		return out, nil
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	byID := make(map[string]int, len(batch.Intents))
	for i := range batch.Intents {
		it := &batch.Intents[i]
		res := ItemResult{ID: it.ID}

		// 1. 参数校验（含批次内重复编号：第二个起一律按编号冲突报告）。
		amount, reason, ok := validateIntent(*it)
		if !ok {
			res.Status = StatusInvalid
			res.Reason = reason
			out.Results = append(out.Results, res)
			if it.ID != "" {
				byID[it.ID] = i
			}
			continue
		}
		if prev, dup := byID[it.ID]; dup {
			res.Status = StatusConflict
			res.Reason = fmt.Sprintf("%s: id repeated within this batch (first at index %d)", reasonConflict, prev)
			out.Results = append(out.Results, res)
			byID[it.ID] = i
			continue
		}
		byID[it.ID] = i

		// 2. 状态错误单独报告。
		if it.State != "" && it.State != "pending" {
			res.Status = StatusState
			res.Reason = reasonNotPending
			out.Results = append(out.Results, res)
			continue
		}

		// 3. 已成功编号：幂等或冲突，均不扣款。
		if rec, exists := l.findRecord(it.ID); exists {
			if sameRequest(rec, it, amount, batch.FeeBps) {
				cp := rec
				res.Status = StatusDuplicate
				res.Reason = reasonDuplicate
				res.Record = &cp
			} else {
				res.Status = StatusConflict
				res.Reason = reasonConflict
			}
			out.Results = append(out.Results, res)
			continue
		}

		// 4. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
		fee := feeFor(amount, batch.FeeBps)
		total := addChecked(amount, fee)
		key := balanceKey{it.Account, it.Asset}
		bal := l.state.Balances[key]
		if total < 0 || total > bal {
			res.Status = StatusFunds
			res.Reason = reasonFunds
			out.Results = append(out.Results, res)
			continue
		}

		// 5. 先在内存生效，再原子持久化；保存失败整体回滚该项。
		rec := Record{
			ID:        it.ID,
			Account:   it.Account,
			Paymaster: it.Paymaster,
			Asset:     it.Asset,
			Amount:    amount,
			Nonce:     it.Nonce,
			FeeBps:    batch.FeeBps,
			Fee:       fee,
			Charged:   total,
			Seq:       int64(len(l.state.Settlements)) + 1,
		}
		rollback := l.stage(key, bal-total, rec)
		if err := l.persist(); err != nil {
			rollback()
			res.Status = StatusStorage
			res.Reason = err.Error()
		} else {
			cp := rec
			res.Status = StatusSettled
			res.Record = &cp
		}
		out.Results = append(out.Results, res)
	}
	return out, nil
}

// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
	oldBal, hadKey := l.state.Balances[key]
	oldLen := len(l.state.Settlements)
	l.state.Balances[key] = newBal
	l.state.Settlements = append(l.state.Settlements, rec)
	return func() {
		if hadKey {
			l.state.Balances[key] = oldBal
		} else {
			delete(l.state.Balances, key)
		}
		l.state.Settlements = l.state.Settlements[:oldLen]
	}
}

func (l *Ledger) findRecord(id string) (Record, bool) {
	// 记录按成功顺序追加且 ID 唯一；顺序扫描简单且保持顺序语义。
	for _, r := range l.state.Settlements {
		if r.ID == id {
			return r, true
		}
	}
	return Record{}, false
}

// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
	return r.Account == it.Account &&
		r.Paymaster == it.Paymaster &&
		r.Asset == it.Asset &&
		r.Amount == amount &&
		r.Nonce == it.Nonce &&
		r.FeeBps == feeBps
}

// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
func (l *Ledger) Query() (*Snapshot, error) {
	if err := l.locked(); err != nil {
		return nil, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	bals := make([]BalanceView, 0, len(l.state.Balances))
	for k, v := range l.state.Balances {
		bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
	}
	sortBalances(bals)
	recs := make([]Record, len(l.state.Settlements))
	copy(recs, l.state.Settlements)
	return &Snapshot{Balances: bals, Settlements: recs}, nil
}

// Balance 返回单个 (账户, 资产) 组合的余额；不存在按 0 处理。
func (l *Ledger) Balance(account, asset string) (int64, error) {
	if err := l.locked(); err != nil {
		return 0, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.state.Balances[balanceKey{account, asset}], nil
}

// persist 将当前状态原子写入磁盘。failHook 仅供测试注入存储故障。
func (l *Ledger) persist() error {
	if l.failHook != nil && l.failHook.FailNextPersist() {
		return ledgerError(ErrStorage, "injected write failure")
	}
	return atomicWrite(l.path, l.state)
}

// failHook 由测试通过 SetFailHook 设置（生产代码不触碰）。
var failHooks sync.Map // *Ledger -> FailWriter

// SetFailHook 为指定账本安装存储故障注入，仅用于测试。
func SetFailHook(l *Ledger, fw FailWriter) {
	if fw == nil {
		failHooks.Delete(l)
		return
	}
	failHooks.Store(l, fw)
}

func init() {
	_ = binary.LittleEndian // keep encoding/binary import stable if extended later
}

toolUseResult.content:
package payflow

import (
	"bytes"
	"encoding/binary"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"math"
	"os"
	"path/filepath"
	"sync"
)

// 账本磁盘格式（单文件，JSON 一行）：
//
//	{"version":1,"balances":{"account\x00asset":1000},
//	 "settlements":[{...一笔成功结算及其当时费率...}]}
//
// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
// 不会出现“扣款无记录”或“记录无扣款”的中间状态。
const ledgerVersion = 1

// 结算结果状态，与命令行输出一一对应，可分别识别。
const (
	StatusSettled   = "settled"    // 成功扣款
	StatusDuplicate = "duplicate"  // 幂等重试：字段与原记录一致，返回原结算，不再扣款
	StatusConflict  = "conflict"   // 编号冲突：编号已成功但字段或费率不同
	StatusState     = "state_error"
	StatusFunds     = "insufficient_balance"
	StatusInvalid   = "invalid_parameter"
	StatusStorage   = "storage_error"
)

// 拒绝原因。
const (
	reasonEmptyID      = "intent id must not be empty"
	reasonEmptyAccount = "account must not be empty"
	reasonEmptyAsset   = "asset must not be empty"
	reasonBadAmount    = "amount must be a positive int64"
	reasonNotPending   = "intent is not pending"
	reasonFunds        = "insufficient balance for amount plus fee"
	reasonDuplicate    = "duplicate settlement attempt"
	reasonConflict     = "settlement id conflicts with a different request"
)

// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
type BalanceInit struct {
	Account string `json:"account"`
	Asset   string `json:"asset"`
	Balance int64  `json:"balance"`
}

// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/为 0”与正数。
type PaymentIntent struct {
	ID        string `json:"id"`
	Account   string `json:"account"`
	Paymaster string `json:"paymaster"`
	Asset     string `json:"asset"`
	Amount    *int64 `json:"amount"`
	Nonce     uint64 `json:"nonce"`
	State     string `json:"state"`
}

// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表。
type FeeBatch struct {
	FeeBps  int             `json:"fee_bps"`
	Intents []PaymentIntent `json:"intents"`
}

// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
type Record struct {
	ID        string `json:"id"`
	Account   string `json:"account"`
	Paymaster string `json:"paymaster"`
	Asset     string `json:"asset"`
	Amount    int64  `json:"amount"`
	Nonce     uint64 `json:"nonce"`
	FeeBps    int    `json:"fee_bps"`
	Fee       int64  `json:"fee"`
	Charged   int64  `json:"charged"`
	Seq       int64  `json:"seq"`
}

// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
type ItemResult struct {
	ID     string  `json:"id"`
	Status string  `json:"status"`
	Reason string  `json:"reason,omitempty"`
	Record *Record `json:"record,omitempty"`
}

// BatchResult 是一次提交的结果。
type BatchResult struct {
	Results []ItemResult `json:"results"`
}

// BalanceView 是一个 (账户, 资产) 组合的当前余额。
type BalanceView struct {
	Account string `json:"account"`
	Asset   string `json:"asset"`
	Balance int64  `json:"balance"`
}

// Snapshot 是账本查询结果。
type Snapshot struct {
	Balances    []BalanceView `json:"balances"`
	Settlements []Record      `json:"settlements"`
}

// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
type LedgerError struct {
	Kind    string
	Message string
}

func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }

// 错误分类。
const (
	ErrInvalid   = "invalid_parameter"
	ErrExists    = "ledger_exists"
	ErrCorrupt   = "corrupt_ledger"
	ErrStorage   = "storage_error"
	ErrClosed    = "ledger_closed"
	ErrNotInit   = "ledger_not_initialized"
	ErrOtherOpen = "ledger_open_elsewhere"
)

func ledgerError(kind, format string, args ...any) error {
	return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
}

// KindOf 返回错误的分类；非账本错误返回 "storage_error"。
func KindOf(err error) string {
	var le *LedgerError
	if errors.As(err, &le) {
		return le.Kind
	}
	return ErrStorage
}

// FailWriter 注入存储故障：返回 true 时本次持久化失败，
// 内存状态必须回滚到该项执行之前。仅用于测试。
type FailWriter interface {
	FailNextPersist() bool
}

type balanceKey struct {
	account string
	asset   string
}

type ledgerState struct {
	Version     int                `json:"version"`
	Balances    map[balanceKey]int64 `json:"-"`
	Settlements []Record           `json:"settlements"`
}

// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
// 返回同一实例并共享互斥锁，因此并发提交按同一本账本串行化。
type Ledger struct {
	path string
	mu   *sync.Mutex

	// registry 级别共享状态，见 openRegistries。
	state *ledgerState
	open  bool
	reg   *registryEntry
}

type registryEntry struct {
	mu     sync.Mutex
	state  *ledgerState
	refs   int
	sole   *Ledger // 最近一次以写模式打开的实例，用于排他性校验
}

var (
	openMu       sync.Mutex
	openRegistry = map[string]*registryEntry{}
)

// persistedState 是磁盘 JSON 的实际结构。
type persistedState struct {
	Version  int                       `json:"version"`
	Balances map[string]json.RawMessage `json:"balances"`
	Records  []Record                  `json:"settlements"`
}

// MarshalJSON 让复合键以 "account\x00asset" 落盘。
func (s *ledgerState) MarshalJSON() ([]byte, error) {
	bal := make(map[string]int64, len(s.Balances))
	for k, v := range s.Balances {
		bal[encodeBalanceKey(k)] = v
	}
	return json.Marshal(struct {
		Version     int            `json:"version"`
		Balances    map[string]int64 `json:"balances"`
		Settlements []Record       `json:"settlements"`
	}{s.Version, bal, s.Settlements})
}

func encodeBalanceKey(k balanceKey) string { return k.account + "\x00" + k.asset }

func decodeBalanceKey(raw string) (balanceKey, bool) {
	for i := 0; i < len(raw); i++ {
		if raw[i] == 0 {
			return balanceKey{account: raw[:i], asset: raw[i+1:]}, true
		}
	}
	return balanceKey{}, false
}

func decodeState(p persistedState) (*ledgerState, error) {
	if p.Version != ledgerVersion {
		return nil, ledgerError(ErrCorrupt, "unsupported ledger version %d", p.Version)
	}
	if p.Balances == nil {
		return nil, ledgerError(ErrCorrupt, "missing balances section")
	}
	bals := make(map[balanceKey]int64, len(p.Balances))
	for key, raw := range p.Balances {
		k, ok := decodeBalanceKey(key)
		if !ok {
			return nil, ledgerError(ErrCorrupt, "malformed balance key %q", key)
		}
		var v int64
		if err := json.Unmarshal(raw, &v); err != nil {
			return nil, ledgerError(ErrCorrupt, "balance for %s/%s is not an int64: %v", k.account, k.asset, err)
		}
		if v < 0 {
			return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", k.account, k.asset)
		}
		bals[k] = v
	}
	seen := map[string]bool{}
	for i, r := range p.Records {
		if r.ID == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %d has empty id", i)
		}
		if seen[r.ID] {
			return nil, ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
		}
		seen[r.ID] = true
		if r.Amount <= 0 || r.Charged <= 0 || r.Fee < 0 || r.Charged != addChecked(r.Amount, r.Fee) {
			return nil, ledgerError(ErrCorrupt, "settlement %q has inconsistent amounts", r.ID)
		}
		if r.Account == "" || r.Asset == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
		}
		if r.FeeBps < 0 || r.FeeBps > 10000 {
			return nil, ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
		}
	}
	return &ledgerState{Version: p.Version, Balances: bals, Settlements: p.Records}, nil
}

func addChecked(a, b int64) int64 {
	if b > math.MaxInt64-a {
		return math.MinInt64 // 哨兵：溢出，任何真实扣款总额不可能为负
	}
	return a + b
}

// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
// 任一不合法则返回 ErrInvalid 且不创建任何文件；
// 路径上已有账本文件则返回 ErrExists，绝不覆盖历史。
func CreateLedger(path string, init []BalanceInit) error {
	if err := validateInitial(init); err != nil {
		return err
	}
	abs, err := filepath.Abs(path)
	if err != nil {
		return ledgerError(ErrStorage, "resolve path: %v", err)
	}

	openMu.Lock()
	defer openMu.Unlock()

	if _, err := os.Stat(abs); err == nil {
		return ledgerError(ErrExists, "ledger already exists at %s", abs)
	} else if !errors.Is(err, os.ErrNotExist) {
		return ledgerError(ErrStorage, "stat %s: %v", abs, err)
	}
	if reg := openRegistry[abs]; reg != nil {
		return ledgerError(ErrExists, "ledger is already initialized in this process")
	}

	state := &ledgerState{
		Version:     ledgerVersion,
		Balances:    make(map[balanceKey]int64, len(init)),
		Settlements: []Record{},
	}
	for _, b := range init {
		state.Balances[balanceKey{b.Account, b.Asset}] = b.Balance
	}
	if err := atomicWrite(abs, state); err != nil {
		return err
	}
	reg := &registryEntry{state: state}
	openRegistry[abs] = reg
	return nil
}

func validateInitial(init []BalanceInit) error {
	seen := map[balanceKey]bool{}
	for i, b := range init {
		if b.Account == "" {
			return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
		}
		if b.Asset == "" {
			return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
		}
		if b.Balance < 0 {
			return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
		}
		k := balanceKey{b.Account, b.Asset}
		if seen[k] {
			return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
		}
		seen[k] = true
	}
	return nil
}

// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
func Open(path string) (*Ledger, error) {
	abs, err := filepath.Abs(path)
	if err != nil {
		return nil, ledgerError(ErrStorage, "resolve path: %v", err)
	}

	openMu.Lock()
	defer openMu.Unlock()

	if reg := openRegistry[abs]; reg != nil {
		l := &Ledger{path: abs, mu: &reg.mu, state: reg.state, open: true, reg: reg}
		reg.refs++
		return l, nil
	}

	data, err := os.ReadFile(abs)
	if err != nil {
		if errors.Is(err, os.ErrNotExist) {
			return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
		}
		return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
	}
	if len(bytes.TrimSpace(data)) == 0 {
		return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
	}
	var p persistedState
	dec := json.NewDecoder(bytes.NewReader(data))
	if err := dec.Decode(&p); err != nil {
		return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
	}
	// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
	if tok, err := dec.Token(); err != io.EOF {
		if err == nil {
			return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
		}
		return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
	}
	state, err := decodeState(p)
	if err != nil {
		var le *LedgerError
		if errors.As(err, &le) && le.Kind == ErrCorrupt {
			return nil, err
		}
		return nil, ledgerError(ErrCorrupt, "%v", err)
	}

	reg := &registryEntry{state: state, refs: 1}
	openRegistry[abs] = reg
	return &Ledger{path: abs, mu: &reg.mu, state: state, open: true, reg: reg}, nil
}

// Close 释放句柄；同一进程可再次 Open 同一文件。
func (l *Ledger) Close() error {
	openMu.Lock()
	defer openMu.Unlock()
	if !l.open {
		return nil
	}
	l.open = false
	l.reg.refs--
	if l.reg.refs <= 0 {
		delete(openRegistry, l.path)
	}
	return nil
}

func (l *Ledger) locked() error {
	if !l.open {
		return ledgerError(ErrClosed, "ledger handle is closed")
	}
	return nil
}

// feeFor 计算手续费：amount*feeBps/10000 向下取整；amount>0、0<=feeBps<=10000
// 时乘积不会溢出 int64（上限 10000*MaxInt64 < MaxInt64*2^14）。
func feeFor(amount int64, feeBps int) int64 {
	hi := amount / 10000
	lo := amount % 10000
	return hi*int64(feeBps) + (lo*int64(feeBps))/10000
}

func validateIntent(it PaymentIntent) (int64, string, bool) {
	if it.ID == "" {
		return 0, reasonEmptyID, false
	}
	if it.Account == "" {
		return 0, reasonEmptyAccount, false
	}
	if it.Asset == "" {
		return 0, reasonEmptyAsset, false
	}
	if it.Amount == nil || *it.Amount <= 0 {
		return 0, reasonBadAmount, false
	}
	return *it.Amount, "", true
}

// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
// 成功后的余额；任何一项失败都不影响其余项（存储错误除外——该项回滚
// 到执行前，而已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
	if err := l.locked(); err != nil {
		return nil, err
	}
	if batch.FeeBps < 0 || batch.FeeBps > 10000 {
		return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
	}
	out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
	if len(batch.Intents) == 0 {
		return out, nil
	}

	l.mu.Lock()
	defer l.mu.Unlock()

	byID := make(map[string]int, len(batch.Intents))
	for i := range batch.Intents {
		it := &batch.Intents[i]
		res := ItemResult{ID: it.ID}

		// 1. 参数校验（含批次内重复编号：第二个起一律按编号冲突报告）。
		amount, reason, ok := validateIntent(*it)
		if !ok {
			res.Status = StatusInvalid
			res.Reason = reason
			out.Results = append(out.Results, res)
			if it.ID != "" {
				byID[it.ID] = i
			}
			continue
		}
		if prev, dup := byID[it.ID]; dup {
			res.Status = StatusConflict
			res.Reason = fmt.Sprintf("%s: id repeated within this batch (first at index %d)", reasonConflict, prev)
			out.Results = append(out.Results, res)
			byID[it.ID] = i
			continue
		}
		byID[it.ID] = i

		// 2. 状态错误单独报告。
		if it.State != "" && it.State != "pending" {
			res.Status = StatusState
			res.Reason = reasonNotPending
			out.Results = append(out.Results, res)
			continue
		}

		// 3. 已成功编号：幂等或冲突，均不扣款。
		if rec, exists := l.findRecord(it.ID); exists {
			if sameRequest(rec, it, amount, batch.FeeBps) {
				cp := rec
				res.Status = StatusDuplicate
				res.Reason = reasonDuplicate
				res.Record = &cp
			} else {
				res.Status = StatusConflict
				res.Reason = reasonConflict
			}
			out.Results = append(out.Results, res)
			continue
		}

		// 4. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
		fee := feeFor(amount, batch.FeeBps)
		total := addChecked(amount, fee)
		key := balanceKey{it.Account, it.Asset}
		bal := l.state.Balances[key]
		if total < 0 || total > bal {
			res.Status = StatusFunds
			res.Reason = reasonFunds
			out.Results = append(out.Results, res)
			continue
		}

		// 5. 先在内存生效，再原子持久化；保存失败整体回滚该项。
		rec := Record{
			ID:        it.ID,
			Account:   it.Account,
			Paymaster: it.Paymaster,
			Asset:     it.Asset,
			Amount:    amount,
			Nonce:     it.Nonce,
			FeeBps:    batch.FeeBps,
			Fee:       fee,
			Charged:   total,
			Seq:       int64(len(l.state.Settlements)) + 1,
		}
		rollback := l.stage(key, bal-total, rec)
		if err := l.persist(); err != nil {
			rollback()
			res.Status = StatusStorage
			res.Reason = err.Error()
		} else {
			cp := rec
			res.Status = StatusSettled
			res.Record = &cp
		}
		out.Results = append(out.Results, res)
	}
	return out, nil
}

// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
	oldBal, hadKey := l.state.Balances[key]
	oldLen := len(l.state.Settlements)
	l.state.Balances[key] = newBal
	l.state.Settlements = append(l.state.Settlements, rec)
	return func() {
		if hadKey {
			l.state.Balances[key] = oldBal
		} else {
			delete(l.state.Balances, key)
		}
		l.state.Settlements = l.state.Settlements[:oldLen]
	}
}

func (l *Ledger) findRecord(id string) (Record, bool) {
	// 记录按成功顺序追加且 ID 唯一；顺序扫描简单且保持顺序语义。
	for _, r := range l.state.Settlements {
		if r.ID == id {
			return r, true
		}
	}
	return Record{}, false
}

// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
	return r.Account == it.Account &&
		r.Paymaster == it.Paymaster &&
		r.Asset == it.Asset &&
		r.Amount == amount &&
		r.Nonce == it.Nonce &&
		r.FeeBps == feeBps
}

// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
func (l *Ledger) Query() (*Snapshot, error) {
	if err := l.locked(); err != nil {
		return nil, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()

	bals := make([]BalanceView, 0, len(l.state.Balances))
	for k, v := range l.state.Balances {
		bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
	}
	sortBalances(bals)
	recs := make([]Record, len(l.state.Settlements))
	copy(recs, l.state.Settlements)
	return &Snapshot{Balances: bals, Settlements: recs}, nil
}

// Balance 返回单个 (账户, 资产) 组合的余额；不存在按 0 处理。
func (l *Ledger) Balance(account, asset string) (int64, error) {
	if err := l.locked(); err != nil {
		return 0, err
	}
	l.mu.Lock()
	defer l.mu.Unlock()
	return l.state.Balances[balanceKey{account, asset}], nil
}

// persist 将当前状态原子写入磁盘。failHook 仅供测试注入存储故障。
func (l *Ledger) persist() error {
	if l.failHook != nil && l.failHook.FailNextPersist() {
		return ledgerError(ErrStorage, "injected write failure")
	}
	return atomicWrite(l.path, l.state)
}

// failHook 由测试通过 SetFailHook 设置（生产代码不触碰）。
var failHooks sync.Map // *Ledger -> FailWriter

// SetFailHook 为指定账本安装存储故障注入，仅用于测试。
func SetFailHook(l *Ledger, fw FailWriter) {
	if fw == nil {
		failHooks.Delete(l)
		return
	}
	failHooks.Store(l, fw)
}

func init() {
	_ = binary.LittleEndian // keep encoding/binary import stable if extended later
}

