package payflow

import (
	"encoding/json"
	"errors"
	"fmt"
	"math"
	"os"
	"path/filepath"
)

// atomicWrite 将 v 以 JSON 原子写入 path：
//  1. 写入同目录临时文件并 fsync；
//  2. rename 覆盖目标文件（同文件系统内原子）；
//  3. fsync 目录，保证 rename 落盘。
//
// 任一步骤失败都返回存储错误且不动旧文件；进程在写入期间崩溃时，
// 重开只能看到完整的旧状态或新状态。
func atomicWrite(path string, v any, perm os.FileMode) error {
	if perm == 0 {
		perm = 0o600
	}
	data, err := json.Marshal(v)
	if err != nil {
		return ledgerError(ErrStorage, "encode ledger: %v", err)
	}
	data = append(data, '\n')

	dir := filepath.Dir(path)
	if err := os.MkdirAll(dir, 0o700); err != nil {
		return ledgerError(ErrStorage, "create ledger directory %s: %v", dir, err)
	}

	tmp, err := os.CreateTemp(dir, ".ledger-*.tmp")
	if err != nil {
		return ledgerError(ErrStorage, "create temp file in %s: %v", dir, err)
	}
	tmpName := tmp.Name()
	cleanup := func() { _ = os.Remove(tmpName) }

	if _, err := tmp.Write(data); err != nil {
		_ = tmp.Close()
		cleanup()
		return ledgerError(ErrStorage, "write temp file: %v", err)
	}
	if err := tmp.Sync(); err != nil {
		_ = tmp.Close()
		cleanup()
		return ledgerError(ErrStorage, "fsync temp file: %v", err)
	}
	if err := tmp.Close(); err != nil {
		cleanup()
		return ledgerError(ErrStorage, "close temp file: %v", err)
	}
	if err := os.Chmod(tmpName, perm); err != nil {
		cleanup()
		return ledgerError(ErrStorage, "chmod temp file: %v", err)
	}
	if err := os.Rename(tmpName, path); err != nil {
		cleanup()
		return ledgerError(ErrStorage, "rename into place: %v", err)
	}
	if err := syncDir(dir); err != nil {
		// rename 已完成；目录 fsync 失败时新旧状态仍完整，仅持久性保证减弱，按存储错误上报。
		return ledgerError(ErrStorage, "fsync directory %s: %v", dir, err)
	}
	return nil
}

func syncDir(dir string) error {
	d, err := os.Open(dir)
	if err != nil {
		return err
	}
	defer d.Close()
	return d.Sync()
}

// validateAndReplay 在解码后重放全部成功记录，重建初始余额并验证：
// 序列连续、费用一致、任一时点余额非负且不溢出。任何不符都判定账本损坏。
func validateAndReplay(final map[balanceKey]int64, records []Record) (map[balanceKey]int64, error) {
	charged := make(map[balanceKey]int64)
	seen := map[string]bool{}
	for i, r := range records {
		if r.ID == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %d has empty id", i)
		}
		if seen[r.ID] {
			return nil, ledgerError(ErrCorrupt, "duplicate settlement id %q", r.ID)
		}
		seen[r.ID] = true
		if r.Account == "" || r.Asset == "" {
			return nil, ledgerError(ErrCorrupt, "settlement %q missing account or asset", r.ID)
		}
		if r.Amount <= 0 || r.Fee < 0 || r.Charged <= 0 {
			return nil, ledgerError(ErrCorrupt, "settlement %q has non-positive amounts", r.ID)
		}
		if r.FeeBps < 0 || r.FeeBps > 10000 {
			return nil, ledgerError(ErrCorrupt, "settlement %q has invalid fee bps", r.ID)
		}
		if want := feeFor(r.Amount, r.FeeBps); want != r.Fee {
			return nil, ledgerError(ErrCorrupt, "settlement %q fee mismatch: file %d, want %d", r.ID, r.Fee, want)
		}
		if r.Charged != r.Amount+r.Fee {
			return nil, ledgerError(ErrCorrupt, "settlement %q charged != amount + fee", r.ID)
		}
		if int64(i)+1 != r.Seq {
			return nil, ledgerError(ErrCorrupt, "settlement %q sequence gap", r.ID)
		}
		k := balanceKey{r.Account, r.Asset}
		sum := charged[k]
		if r.Charged > math.MaxInt64-sum {
			return nil, ledgerError(ErrCorrupt, "settlement %q cumulative charges overflow int64", r.ID)
		}
		charged[k] = sum + r.Charged
	}

	// 初始余额 = 当前余额 + 全部扣款；余额只减不增。
	initial := make(map[balanceKey]int64, len(final))
	keys := map[balanceKey]bool{}
	for k, v := range final {
		keys[k] = true
		if c := charged[k]; c > math.MaxInt64-v {
			return nil, ledgerError(ErrCorrupt, "reconstructed initial balance overflows int64 for %s/%s", k.account, k.asset)
		}
		initial[k] = v + charged[k]
	}
	for k := range charged {
		if !keys[k] {
			// 曾被扣成 0 的组合：当前余额 0，初始余额 = 累计扣款。
			keys[k] = true
			initial[k] = charged[k]
		}
	}

	// 按记录顺序重放，任一时点不得为负。
	working := make(map[balanceKey]int64, len(initial))
	for k, v := range initial {
		working[k] = v
	}
	for _, r := range records {
		k := balanceKey{r.Account, r.Asset}
		bal := working[k]
		if r.Charged > bal {
			return nil, ledgerError(ErrCorrupt, "settlement %q drives %s/%s negative", r.ID, r.Account, r.Asset)
		}
		working[k] = bal - r.Charged
	}
	// 重放结果必须等于文件中的最终余额。
	for k, got := range working {
		if got != final[k] {
			return nil, ledgerError(ErrCorrupt, "final balance mismatch for %s/%s: replay %d, file %d", k.account, k.asset, got, final[k])
		}
	}
	return initial, nil
}

// ensureNoLeftoverTemp 报告目录中残留的临时文件——正常流程不会留下，
// 存在即说明上次写入异常中断（旧文件仍是完整的，可读但需提示）。
// 当前策略：不阻止打开旧账本；仅在调试时可观察，保留函数以便扩展。
func ensureNoLeftoverTemp(dir string) error {
	patterns, err := filepath.Glob(filepath.Join(dir, ".ledger-*.tmp"))
	if err != nil {
		return err
	}
	if len(patterns) > 0 {
		return fmt.Errorf("%w: leftover temp files %v", errCorruptSentinel, patterns)
	}
	return nil
}

var errCorruptSentinel = errors.New("ledger write did not finish")

