content.content:
1	package payflow
2	
3	import (
4		"bytes"
5		"encoding/json"
6		"errors"
7		"fmt"
8		"io"
9		"math"
10		"os"
11		"path/filepath"
12		"sort"
13		"sync"
14	)
15	
16	// 账本磁盘格式（单文件，一个 JSON 文档）：
17	//
18	//	{"version":1,"balances":{"account\u0000asset":1000},
19	//	 "settlements":[{...一笔成功结算及其当时费率...}]}
20	//
21	// 写入采用“临时文件 + fsync + 原子 rename + 目录 fsync”，
22	// 因此崩溃后磁盘上只会存在完整的旧版本或完整新版本，
23	// 不会出现“扣款无记录”或“记录未扣款”的中间状态。
24	const ledgerVersion = 1
25	
26	// 结算结果状态，与命令行输出一一对应，可分别识别。
27	const (
28		StatusSettled   = "settled"              // 成功扣款
29		StatusDuplicate = "duplicate"            // 幂等重试：字段与原记录一致，返回原结算，不再扣款
30		StatusConflict  = "conflict"             // 编号冲突：编号已成功但字段或费率不同
31		StatusState     = "state_error"          // 非 pending
32		StatusFunds     = "insufficient_balance" // 余额不足（含不存在的账户/资产组合）
33		StatusInvalid   = "invalid_parameter"
34		StatusStorage   = "storage_error"
35	)
36	
37	// 拒绝原因。
38	const (
39		reasonEmptyID      = "intent id must not be empty"
40		reasonEmptyAccount = "account must not be empty"
41		reasonEmptyAsset   = "asset must not be empty"
42		reasonBadAmount    = "amount must be a positive int64"
43		reasonBadFee       = "fee must be amount * fee_bps / 10000"
44		reasonOverflow     = "amount plus fee overflows int64"
45		reasonNotPending   = "intent is not pending"
46		reasonFunds        = "insufficient balance for amount plus fee"
47		reasonDuplicate    = "duplicate settlement attempt"
48		reasonConflict     = "settlement id conflicts with a different request"
49	)
50	
51	// BalanceInit 是初始化时一个 (账户, 资产) 组合的起始余额。
52	type BalanceInit struct {
53		Account string `json:"account"`
54		Asset   string `json:"asset"`
55		Balance int64  `json:"balance"`
56	}
57	
58	// PaymentIntent 是批次中的一项付款请求。金额使用指针以区分“缺省/null”与 0。
59	type PaymentIntent struct {
60		ID        string `json:"id"`
61		Account   string `json:"account"`
62		Paymaster string `json:"paymaster"`
63		Asset     string `json:"asset"`
64		Amount    *int64 `json:"amount"`
65		Nonce     uint64 `json:"nonce"`
66		State     string `json:"state"`
67	}
68	
69	// FeeBatch 是一次提交：固定费率（基点）+ 有序意图列表。
70	type FeeBatch struct {
71		FeeBps  int             `json:"fee_bps"`
72		Intents []PaymentIntent `json:"intents"`
73	}
74	
75	// Record 是一笔成功结算留下的永久记录，按成功先后顺序保存。
76	type Record struct {
77		ID        string `json:"id"`
78		Account   string `json:"account"`
79		Paymaster string `json:"paymaster"`
80		Asset     string `json:"asset"`
81		Amount    int64  `json:"amount"`
82		Nonce     uint64 `json:"nonce"`
83		FeeBps    int    `json:"fee_bps"`
84		Fee       int64  `json:"fee"`
85		Charged   int64  `json:"charged"`
86		Seq       int64  `json:"seq"`
87	}
88	
89	// ItemResult 是批次中一项的处理结果，顺序与输入逐项对应。
90	type ItemResult struct {
91		ID     string  `json:"id"`
92		Status string  `json:"status"`
93		Reason string  `json:"reason,omitempty"`
94		Record *Record `json:"record,omitempty"`
95	}
96	
97	// BatchResult 是一次提交的结果。空批次对应空 Results。
98	type BatchResult struct {
99		Results []ItemResult `json:"results"`
100	}
101	
102	// BalanceView 是一个 (账户, 资产) 组合的当前余额。
103	type BalanceView struct {
104		Account string `json:"account"`
105		Asset   string `json:"asset"`
106		Balance int64  `json:"balance"`
107	}
108	
109	// Snapshot 是账本查询结果。
110	type Snapshot struct {
111		Balances    []BalanceView `json:"balances"`
112		Settlements []Record      `json:"settlements"`
113	}
114	
115	// LedgerError 携带可机读分类（与 ItemResult.Status 对齐）和说明。
116	type LedgerError struct {
117		Kind    string
118		Message string
119	}
120	
121	func (e *LedgerError) Error() string { return e.Kind + ": " + e.Message }
122	
123	// 错误分类。
124	const (
125		ErrInvalid = "invalid_parameter"
126		ErrExists  = "ledger_exists"
127		ErrCorrupt = "corrupt_ledger"
128		ErrStorage = "storage_error"
129		ErrClosed  = "ledger_closed"
130		ErrNotInit = "ledger_not_initialized"
131	)
132	
133	func ledgerError(kind, format string, args ...any) error {
134		return &LedgerError{Kind: kind, Message: fmt.Sprintf(format, args...)}
135	}
136	
137	// KindOf 返回错误的分类；非账本错误按存储错误处理。
138	func KindOf(err error) string {
139		var le *LedgerError
140		if errors.As(err, &le) {
141			return le.Kind
142		}
143		return ErrStorage
144	}
145	
146	// FailWriter 注入存储故障：返回 true 时本次持久化失败，
147	// 内存状态必须回滚到该项执行之前。仅用于测试。
148	type FailWriter interface {
149		FailNextPersist() bool
150	}
151	
152	type balanceKey struct {
153		account string
154		asset   string
155	}
156	
157	type ledgerState struct {
158		Version     int
159		Balances    map[balanceKey]int64
160		Settlements []Record
161	}
162	
163	// MarshalJSON 让复合键以 "account\x00asset" 落盘。
164	func (s *ledgerState) MarshalJSON() ([]byte, error) {
165		bal := make(map[string]int64, len(s.Balances))
166		for k, v := range s.Balances {
167			bal[encodeBalanceKey(k)] = v
168		}
169		type persisted struct {
170			Version     int             `json:"version"`
171			Balances    map[string]int64 `json:"balances"`
172			Settlements []Record        `json:"settlements"`
173		}
174		return json.Marshal(persisted{Version: s.Version, Balances: bal, Settlements: s.Settlements})
175	}
176	
177	func encodeBalanceKey(k balanceKey) string { return k.account + "\x00" + k.asset }
178	
179	func decodeBalanceKey(raw string) (balanceKey, bool) {
180		for i := 0; i < len(raw); i++ {
181			if raw[i] == 0 {
182				return balanceKey{account: raw[:i], asset: raw[i+1:]}, true
183			}
184		}
185		return balanceKey{}, false
186	}
187	
188	type persistedState struct {
189		Version  int             `json:"version"`
190		Balances map[string]int64 `json:"balances"`
191		Records  []Record        `json:"settlements"`
192	}
193	
194	func decodeState(p persistedState) (*ledgerState, error) {
195		if p.Version != ledgerVersion {
196			return nil, ledgerError(ErrCorrupt, "unsupported ledger version %d", p.Version)
197		}
198		if p.Balances == nil {
199			return nil, ledgerError(ErrCorrupt, "missing balances section")
200		}
201		bals := make(map[balanceKey]int64, len(p.Balances))
202		for key, v := range p.Balances {
203			k, ok := decodeBalanceKey(key)
204			if !ok {
205				return nil, ledgerError(ErrCorrupt, "malformed balance key %q", key)
206			}
207			if v < 0 {
208				return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", k.account, k.asset)
209			}
210			bals[k] = v
211		}
212		if err := validateAndReplay(bals, p.Records); err != nil {
213			return nil, err
214		}
215		return &ledgerState{Version: p.Version, Balances: bals, Settlements: p.Records}, nil
216	}
217	
218	// CreateLedger 在 path 处创建新账本。所有初始数据先校验，
219	// 任一不合法则返回 ErrInvalid 且不创建任何文件；
220	// 路径上已有账本则返回 ErrExists，绝不覆盖历史。
221	func CreateLedger(path string, init []BalanceInit) error {
222		if err := validateInitial(init); err != nil {
223			return err
224		}
225		abs, err := filepath.Abs(path)
226		if err != nil {
227			return ledgerError(ErrStorage, "resolve path: %v", err)
228		}
229	
230		openMu.Lock()
231		defer openMu.Unlock()
232	
233		if _, err := os.Stat(abs); err == nil {
234			return ledgerError(ErrExists, "ledger already exists at %s", abs)
235		} else if !errors.Is(err, os.ErrNotExist) {
236			return ledgerError(ErrStorage, "stat %s: %v", abs, err)
237		}
238		if openRegistry[abs] != nil {
239			return ledgerError(ErrExists, "ledger is already initialized in this process")
240		}
241	
242		state := &ledgerState{
243			Version:     ledgerVersion,
244			Balances:    make(map[balanceKey]int64, len(init)),
245			Settlements: []Record{},
246		}
247		for _, b := range init {
248			state.Balances[balanceKey{b.Account, b.Asset}] = b.Balance
249		}
250		if err := atomicWrite(abs, state); err != nil {
251			return err
252		}
253		openRegistry[abs] = &registryEntry{state: state}
254		return nil
255	}
256	
257	func validateInitial(init []BalanceInit) error {
258		seen := map[balanceKey]bool{}
259		for i, b := range init {
260			if b.Account == "" {
261				return ledgerError(ErrInvalid, "initial balance %d: account must not be empty", i)
262			}
263			if b.Asset == "" {
264				return ledgerError(ErrInvalid, "initial balance %d: asset must not be empty", i)
265			}
266			if b.Balance < 0 {
267				return ledgerError(ErrInvalid, "initial balance %d (%s/%s): balance must be non-negative", i, b.Account, b.Asset)
268			}
269			k := balanceKey{b.Account, b.Asset}
270			if seen[k] {
271				return ledgerError(ErrInvalid, "initial balance %d: duplicate entry for %s/%s", i, b.Account, b.Asset)
272			}
273			seen[k] = true
274		}
275		return nil
276	}
277	
278	// Ledger 是一个可持久化的本地账本。同一进程内同一路径的多次 Open
279	// 返回共享同一状态与互斥锁的实例，因此并发提交按同一本账本串行化。
280	type Ledger struct {
281		path string
282		reg  *registryEntry
283		open bool
284	}
285	
286	type registryEntry struct {
287		mu       sync.Mutex
288		state    *ledgerState
289		refs     int
290		failHook FailWriter // 仅测试注入
291	}
292	
293	var (
294		openMu       sync.Mutex
295		openRegistry = map[string]*registryEntry{}
296	)
297	
298	// Open 打开（或复用）path 处的账本。账本必须已由 CreateLedger 初始化；
299	// 文件缺失返回 ErrNotInit，内容损坏返回 ErrCorrupt，不会被当成空账本重来。
300	func Open(path string) (*Ledger, error) {
301		abs, err := filepath.Abs(path)
302		if err != nil {
303			return nil, ledgerError(ErrStorage, "resolve path: %v", err)
304		}
305	
306		openMu.Lock()
307		defer openMu.Unlock()
308	
309		if reg := openRegistry[abs]; reg != nil {
310			reg.refs++
311			return &Ledger{path: abs, reg: reg, open: true}, nil
312		}
313	
314		data, err := os.ReadFile(abs)
315		if err != nil {
316			if errors.Is(err, os.ErrNotExist) {
317				return nil, ledgerError(ErrNotInit, "no ledger at %s; initialize it first", abs)
318			}
319			return nil, ledgerError(ErrStorage, "read %s: %v", abs, err)
320		}
321		if len(bytes.TrimSpace(data)) == 0 {
322			return nil, ledgerError(ErrCorrupt, "ledger file %s is empty", abs)
323		}
324		var p persistedState
325		dec := json.NewDecoder(bytes.NewReader(data))
326		if err := dec.Decode(&p); err != nil {
327			return nil, ledgerError(ErrCorrupt, "parse %s: %v", abs, err)
328		}
329			// 不允许尾随内容：防止文件被拼接/截断后被误读为合法。
330		if tok, err := dec.Token(); err != io.EOF {
331			if err == nil {
332				return nil, ledgerError(ErrCorrupt, "unexpected trailing data after ledger document (token %v)", tok)
333			}
334			return nil, ledgerError(ErrCorrupt, "trailing data after ledger document: %v", err)
335		}
336		state, err := decodeState(p)
337		if err != nil {
338			return nil, err
339		}
340	
341		reg := &registryEntry{state: state, refs: 1}
342		openRegistry[abs] = reg
343		return &Ledger{path: abs, reg: reg, open: true}, nil
344	}
345	
346	// Close 释放句柄；同一进程可再次 Open 同一文件并继续使用。
347	func (l *Ledger) Close() error {
348		openMu.Lock()
349		defer openMu.Unlock()
350		if !l.open {
351			return nil
352		}
353		l.open = false
354		l.reg.refs--
355		if l.reg.refs <= 0 {
356			delete(openRegistry, l.path)
357		}
358		return nil
359	}
360	
361	func (l *Ledger) checkOpen() error {
362		if !l.open {
363			return ledgerError(ErrClosed, "ledger handle is closed")
364		}
365		return nil
366	}
367	
368	// feeFor 计算手续费：amount*feeBps/10000 向下取整。
369	// amount>0、0<=feeBps<=10000 时朴素乘积可能溢出 int64，
370	// 拆成商和余数两部分即可在 int64 内精确完成。
371	func feeFor(amount int64, feeBps int) int64 {
372		hi := amount / 10000
373		lo := amount % 10000
374		return hi*int64(feeBps) + (lo*int64(feeBps))/10000
375	}
376	
377	func validateIntent(it PaymentIntent) (int64, string, bool) {
378		if it.ID == "" {
379			return 0, reasonEmptyID, false
380		}
381		if it.Account == "" {
382			return 0, reasonEmptyAccount, false
383		}
384		if it.Asset == "" {
385			return 0, reasonEmptyAsset, false
386		}
387		if it.Amount == nil || *it.Amount <= 0 {
388			return 0, reasonBadAmount, false
389		}
390		return *it.Amount, "", true
391	}
392	
393	// Submit 按输入顺序结算一个批次。各项独立成功或失败：后项看到前项
394	// 成功后的余额；任一项失败不影响其余项（存储错误只回滚出错项本身，
395	// 已完成的前项不回滚）。结果与输入逐项对应，空批次返回空结果。
396	func (l *Ledger) Submit(batch FeeBatch) (*BatchResult, error) {
397		if err := l.checkOpen(); err != nil {
398			return nil, err
399		}
400		if batch.FeeBps < 0 || batch.FeeBps > 10000 {
401			return nil, ledgerError(ErrInvalid, "fee_bps must be within [0,10000], got %d", batch.FeeBps)
402		}
403		out := &BatchResult{Results: make([]ItemResult, 0, len(batch.Intents))}
404	
405		l.reg.mu.Lock()
406		defer l.reg.mu.Unlock()
407	
408		for i := range batch.Intents {
409			it := &batch.Intents[i]
410			res := ItemResult{ID: it.ID}
411	
412			// 1. 参数校验。未通过的编号不占用去重资格。
413			amount, reason, ok := validateIntent(*it)
414			if !ok {
415				res.Status = StatusInvalid
416				res.Reason = reason
417				out.Results = append(out.Results, res)
418				continue
419			}
420	
421			// 2. 已成功编号：字段与费率完全一致则幂等返回原记录；
422			//    任一不同则编号冲突。两者都不再扣款、不改原记录。
423			//    本批次内先成功的同编号项也在此被看到。
424			if rec, exists := l.findRecord(it.ID); exists {
425				if sameRequest(rec, it, amount, batch.FeeBps) {
426					cp := rec
427					res.Status = StatusDuplicate
428					res.Reason = reasonDuplicate
429					res.Record = &cp
430				} else {
431					res.Status = StatusConflict
432					res.Reason = reasonConflict
433				}
434				out.Results = append(out.Results, res)
435				continue
436			}
437	
438			// 3. 状态错误单独报告（不占用去重资格，之后可重新提交）。
439			if it.State != "" && it.State != "pending" {
440				res.Status = StatusState
441				res.Reason = reasonNotPending
442				out.Results = append(out.Results, res)
443				continue
444			}
445	
446			// 4. 手续费与扣款总额（溢出明确按参数错误拒绝）。
447			fee := feeFor(amount, batch.FeeBps)
448			if fee > math.MaxInt64-amount {
449				res.Status = StatusInvalid
450				res.Reason = reasonOverflow
451				out.Results = append(out.Results, res)
452				continue
453			}
454			total := amount + fee
455	
456			// 5. 余额校验。不存在的账户/资产组合余额视为 0（不足）。
457			key := balanceKey{it.Account, it.Asset}
458			bal := l.reg.state.Balances[key]
459			if total > bal {
460				res.Status = StatusFunds
461				res.Reason = reasonFunds
462				out.Results = append(out.Results, res)
463				continue
464			}
465	
466			// 6. 先在内存生效，再原子持久化；保存失败回滚该项，不留成功记录。
467			rec := Record{
468				ID:        it.ID,
469				Account:   it.Account,
470				Paymaster: it.Paymaster,
471				Asset:     it.Asset,
472				Amount:    amount,
473				Nonce:     it.Nonce,
474				FeeBps:    batch.FeeBps,
475				Fee:       fee,
476				Charged:   total,
477				Seq:       int64(len(l.reg.state.Settlements)) + 1,
478			}
479			rollback := l.stage(key, bal-total, rec)
480			if err := l.persistLocked(); err != nil {
481				rollback()
482				res.Status = StatusStorage
483				res.Reason = err.Error()
484			} else {
485				cp := rec
486				res.Status = StatusSettled
487				res.Record = &cp
488			}
489			out.Results = append(out.Results, res)
490		}
491		return out, nil
492	}
493	
494	// stage 应用一笔扣款与记录，返回回滚函数（恢复该项执行前的余额与记录长度）。
495	func (l *Ledger) stage(key balanceKey, newBal int64, rec Record) func() {
496		oldBal, hadKey := l.reg.state.Balances[key]
497		oldLen := len(l.reg.state.Settlements)
498		l.reg.state.Balances[key] = newBal
499		l.reg.state.Settlements = append(l.reg.state.Settlements, rec)
500		return func() {
501			if hadKey {
502				l.reg.state.Balances[key] = oldBal
503			} else {
504				delete(l.reg.state.Balances, key)
505			}
506			l.reg.state.Settlements = l.reg.state.Settlements[:oldLen]
507		}
508	}
509	
510	func (l *Ledger) stateView() *ledgerState { return l.reg.state }
511	
512	func (l *Ledger) findRecord(id string) (Record, bool) {
513		// 记录按成功顺序追加且 ID 唯一；条目规模在单机账本量级，直接扫描。
514		for _, r := range l.stateView().Settlements {
515			if r.ID == id {
516				return r, true
517			}
518		}
519		return Record{}, false
520	}
521	
522	// sameRequest 比较全部付款字段与费率。付款字段：账户、付款方、资产、金额、nonce。
523	func sameRequest(r Record, it *PaymentIntent, amount int64, feeBps int) bool {
524		return r.Account == it.Account &&
525			r.Paymaster == it.Paymaster &&
526			r.Asset == it.Asset &&
527			r.Amount == amount &&
528			r.Nonce == it.Nonce &&
529			r.FeeBps == feeBps
530	}
531	
532	// Query 返回余额视图（按账户、资产排序，保证确定性）与按成功先后排列的记录。
533	func (l *Ledger) Query() (*Snapshot, error) {
534		if err := l.checkOpen(); err != nil {
535			return nil, err
536		}
537		l.reg.mu.Lock()
538		defer l.reg.mu.Unlock()
539	
540		st := l.stateView()
541		bals := make([]BalanceView, 0, len(st.Balances))
542		for k, v := range st.Balances {
543			bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
544		}
545		sortBalances(bals)
546		recs := make([]Record, len(st.Settlements))
547		copy(recs, st.Settlements)
548		return &Snapshot{Balances: bals, Settlements: recs}, nil
549	}
550	
551	// Balance 返回单个 (账户, 资产) 组合的余额；组合不存在按 0 处理。
552	func (l *Ledger) Balance(account, asset string) (int64, error) {
553		if err := l.checkOpen(); err != nil {
554			return 0, err
555		}
556		l.reg.mu.Lock()
557		defer l.reg.mu.Unlock()
558		return l.stateView().Balances[balanceKey{account, asset}], nil
559	}
560	
561	func sortBalances(bals []BalanceView) {
562		sort.Slice(bals, func(i, j int) bool {
563			if bals[i].Account != bals[j].Account {
564				return bals[i].Account < bals[j].Account
565			}
566			return bals[i].Asset < bals[j].Asset
567		})
568	}
569	
570	// persistLocked 将当前状态原子写入磁盘；调用方必须持有 reg.mu。
571	func (l *Ledger) persistLocked() error {
572		if l.reg.failHook != nil && l.reg.failHook.FailNextPersist() {
573			return ledgerError(ErrStorage, "injected write failure")
574		}
575		return atomicWrite(l.path, l.stateView())
576	}
577	
578	// SetFailHook 为该路径的账本安装存储故障注入，仅用于测试。
579	func SetFailHook(l *Ledger, fw FailWriter) {
580		l.reg.failHook = fw
581	}
582

