// MarshalJSON 以显式对象列表落盘余额，避免复合键编码冲突，顺序按账户/资产排序。
func (s *ledgerState) MarshalJSON() ([]byte, error) {
	type persisted struct {
		Version     int           `json:"version"`
		Balances    []BalanceView `json:"balances"`
		Settlements []Record      `json:"settlements"`
	}
	bals := make([]BalanceView, 0, len(s.Balances))
	for k, v := range s.Balances {
		bals = append(bals, BalanceView{Account: k.account, Asset: k.asset, Balance: v})
	}
	sortBalances(bals)
	settlements := s.Settlements
	if settlements == nil {
		settlements = []Record{}
	}
	return json.Marshal(persisted{Version: s.Version, Balances: bals, Settlements: settlements})
}

type persistedState struct {
	Version  int           `json:"version"`
	Balances []BalanceView `json:"balances"`
	Records  []Record      `json:"settlements"`
}

func decodeState(p persistedState) (*ledgerState, error) {
	if p.Version != ledgerVersion {
		return nil, ledgerError(ErrCorrupt, "unsupported ledger version %d", p.Version)
	}
	if p.Balances == nil {
		return nil, ledgerError(ErrCorrupt, "missing balances section")
	}
	bals := make(map[balanceKey]int64, len(p.Balances))
	for i, b := range p.Balances {
		if b.Account == "" || b.Asset == "" {
			return nil, ledgerError(ErrCorrupt, "balance %d has empty account or asset", i)
		}
		if b.Balance < 0 {
			return nil, ledgerError(ErrCorrupt, "negative balance for %s/%s", b.Account, b.Asset)
		}
		k := balanceKey{b.Account, b.Asset}
		if _, dup := bals[k]; dup {
			return nil, ledgerError(ErrCorrupt, "duplicate balance entry for %s/%s", b.Account, b.Asset)
		}
		bals[k] = b.Balance
	}
	if err := validateAndReplay(bals, p.Records); err != nil {
		return nil, err
	}
	return &ledgerState{Version: p.Version, Balances: bals, Settlements: p.Records}, nil
}

