// ---- 损坏检测 ----

func corrupt(t *testing.T, path, name string, mutate func([]byte) []byte) {
	t.Helper()
	raw, err := os.ReadFile(path)
	if err != nil {
		t.Fatal(err)
	}
	if err := os.WriteFile(filepath.Join(filepath.Dir(path), name), mutate(raw), 0o600); err != nil {
		t.Fatal(err)
	}
}

func TestCorruptLedgerRejected(t *testing.T) {
	good := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
	l := openOrFail(t, good)
	if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 300)}}); err != nil {
		t.Fatal(err)
	}
	if err := l.Close(); err != nil {
		t.Fatal(err)
	}

	dir := filepath.Dir(good)
	mk := func(name string, mutate func([]byte) []byte) string {
		corrupt(t, good, name, mutate)
		return filepath.Join(dir, name)
	}

	cases := map[string]string{
		"truncated": mk("trunc.json", func(b []byte) []byte { return b[:len(b)/2] }),
		"appended":  mk("appended.json", func(b []byte) []byte { return append(b, []byte("{}")...) }),
		"empty":     filepath.Join(dir, "empty.json"),
	}
	if err := os.WriteFile(cases["empty"], nil, 0o600); err != nil {
		t.Fatal(err)
	}

	// 语义损坏：余额改负、删掉记录造成 seq 空洞、记录 ID 重复、扣款与余额不一致。
	semantic := map[string]func(string){
		"negative.json": func(p string) {
			corrupt(t, good, "negative.json", func(b []byte) []byte {
				return []byte(strings.ReplaceAll(string(b), `"balance":700`, `"balance":-1`))
			})
		},
		"seqgap.json": func(p string) {
			corrupt(t, good, "seqgap.json", func(b []byte) []byte {
				return []byte(strings.ReplaceAll(string(b), `"seq":1`, `"seq":2`))
			})
		},
		"dup_rec.json": func(p string) {
			corrupt(t, good, "dup_rec.json", func(b []byte) []byte {
				s := string(b)
				rec := `"settlements":[`
				i := strings.Index(s, rec)
				var head any
				_ = head
				// 把唯一一条记录复制一份，制造重复 ID。
				start := i + len(rec)
				end := strings.Index(s[start:], "}") + start + 1
				one := s[start:end]
				return []byte(s[:end] + "," + one + s[end:])
			})
		},
		"mismatch.json": func(p string) {
			corrupt(t, good, "mismatch.json", func(b []byte) []byte {
				// 记录扣款 999，但最终余额仍是 700（初始只有 1000，重放会到 1，不一致）。
				s := strings.ReplaceAll(string(b), `"charged":300`, `"charged":999`)
				s = strings.ReplaceAll(s, `"amount":300`, `"amount":999`)
				return []byte(s)
			})
		},
	}
	for name, build := range semantic {
		build(filepath.Join(dir, name))
		cases[name] = filepath.Join(dir, name)
	}

	for name, p := range cases {
		t.Run(name, func(t *testing.T) {
			_, err := Open(p)
			if err == nil || KindOf(err) != ErrCorrupt {
				t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
			}
		})
	}

	// 损坏文件不能通过再次初始化“重开一本空账”。
	if err := CreateLedger(cases["truncated"], nil); KindOf(err) != ErrExists {
		t.Fatalf("init over corrupt file must report ErrExists, got %v", err)
	}
}

// ---- 存储故障：回滚该项，前项保留 ----

type failOnce struct{ remaining int }

func (f *failOnce) FailNextPersist() bool {
	if f.remaining > 0 {
		f.remaining--
		return true
	}
	return false
}

func TestStorageFailureRollsBackItemOnly(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
	l := openOrFail(t, path)
	SetFailHook(l, &failOnce{remaining: 1}) // 下一次持久化失败
	t.Cleanup(func() { SetFailHook(l, nil) })

	res, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
		intent("ok1", "aa", "usdc", 100), // 成功
		intent("boom", "aa", "usdc", 100), // 保存失败 → 回滚该项
		intent("ok2", "aa", "usdc", 100), // 注入只失败一次，后续成功
	}})
	if err != nil {
		t.Fatal(err)
	}
	want := []string{StatusSettled, StatusStorage, StatusSettled}
	if got := statuses(res); fmt.Sprint(got) != fmt.Sprint(want) {
		t.Fatalf("statuses=%v want %v", got, want)
	}
	if bal, _ := l.Balance("aa", "usdc"); bal != 800 {
		t.Fatalf("balance=%d want 800 (前项与后项保留，失败项回滚)", bal)
	}
	snap, _ := l.Query()
	if len(snap.Settlements) != 2 || snap.Settlements[0].ID != "ok1" || snap.Settlements[1].ID != "ok2" {
		t.Fatalf("records after storage failure: %+v", snap.Settlements)
	}

	// 失败编号不占去重资格，可以重新提交成功。
	res2, _ := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("boom", "aa", "usdc", 100)}})
	if res2.Results[0].Status != StatusSettled {
		t.Fatalf("failed-on-storage id retry: %+v", res2.Results[0])
	}

	// 关闭重开：磁盘状态与内存一致，失败项不留痕。
	l2 := openOrFail(t, path)
	snap2, _ := l2.Query()
	if len(snap2.Settlements) != 3 {
		t.Fatalf("after reopen want 3 records, got %+v", snap2.Settlements)
	}
	if bal, _ := l2.Balance("aa", "usdc"); bal != 700 {
		t.Fatalf("after reopen balance=%d want 700", bal)
	}
}

