// 且重放结果必须等于文件中的最终余额。任何不符都判定账本损坏。
func validateAndReplay(initial, final map[balanceKey]int64, records []Record) error {
	charged := make(map[balanceKey]int64)
	seen := map[string]bool{}
	for i, r := range records {
