func TestCorruptLedgerRejected(t *testing.T) {
	good := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 1000}})
	l := openOrFail(t, good)
	if _, err := l.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{intent("p", "aa", "usdc", 300)}}); err != nil {
		t.Fatal(err)
	}
	if err := l.Close(); err != nil {
		t.Fatal(err)
	}

	dir := filepath.Dir(good)
	mk := func(name string, mutate func([]byte) []byte) string {
		corrupt(t, good, name, mutate)
		return filepath.Join(dir, name)
	}

	cases := map[string]string{
		"truncated": mk("trunc.json", func(b []byte) []byte { return b[:len(b)/2] }),
		"appended":  mk("appended.json", func(b []byte) []byte { return append(b, []byte("{}")...) }),
		"empty":     filepath.Join(dir, "empty.json"),
	}
	if err := os.WriteFile(cases["empty"], nil, 0o600); err != nil {
		t.Fatal(err)
	}

	// 语义损坏：余额改负、删掉记录造成 seq 空洞、记录 ID 重复、扣款与余额不一致。
	semantic := map[string]func(string){
		"negative.json": func(p string) {
			corrupt(t, good, "negative.json", func(b []byte) []byte {
				return []byte(strings.ReplaceAll(string(b), `"balance":700`, `"balance":-1`))
			})
		},
		"seqgap.json": func(p string) {
			corrupt(t, good, "seqgap.json", func(b []byte) []byte {
				return []byte(strings.ReplaceAll(string(b), `"seq":1`, `"seq":2`))
			})
		},
		"dup_rec.json": func(p string) {
			corrupt(t, good, "dup_rec.json", func(b []byte) []byte {
				s := string(b)
				rec := `"settlements":[`
				i := strings.Index(s, rec)
				var head any
				_ = head
				// 把唯一一条记录复制一份，制造重复 ID。
				start := i + len(rec)
				end := strings.Index(s[start:], "}") + start + 1
				one := s[start:end]
				return []byte(s[:end] + "," + one + s[end:])
			})
		},
		"mismatch.json": func(p string) {
			corrupt(t, good, "mismatch.json", func(b []byte) []byte {
				// 记录扣款 999，但最终余额仍是 700（初始只有 1000，重放会到 1，不一致）。
				s := strings.ReplaceAll(string(b), `"charged":300`, `"charged":999`)
				s = strings.ReplaceAll(s, `"amount":300`, `"amount":999`)
				return []byte(s)
			})
		},
	}
	for name, build := range semantic {
		build(filepath.Join(dir, name))
		cases[name] = filepath.Join(dir, name)
	}

	for name, p := range cases {
		t.Run(name, func(t *testing.T) {
			_, err := Open(p)
			if err == nil || KindOf(err) != ErrCorrupt {
				t.Fatalf("%s: want ErrCorrupt, got %v", name, err)
			}
		})
	}

	// 损坏文件不能通过再次初始化“重开一本空账”。
	if err := CreateLedger(cases["truncated"], nil); KindOf(err) != ErrExists {
		t.Fatalf("init over corrupt file must report ErrExists, got %v", err)
	}
}

