	if r := runCLIWith(t, []string{"init", "-l", path}, `{"balances":[]}`); r.code != 0 {
		t.Fatalf("init: %s", r.err)
	}
	// 用命令行自身无法写文件，这里通过 init 产生后截断由存储层保证；
